class WordDictionary {
    private final Map<Integer, List<String>> byLength;

    public WordDictionary() {
        byLength = new HashMap<>();
    }

    public void addWord(String word) {
        byLength.computeIfAbsent(word.length(), key -> new ArrayList<>()).add(word);
    }

    public boolean search(String word) {
        List<String> candidates = byLength.get(word.length());
        if (candidates == null) {
            return false;
        }
        for (String candidate : candidates) {
            if (matches(candidate, word)) {
                return true;
            }
        }
        return false;
    }

    private boolean matches(String candidate, String pattern) {
        for (int i = 0; i < pattern.length(); i++) {
            char p = pattern.charAt(i);
            if (p != '.' && p != candidate.charAt(i)) {
                return false;
            }
        }
        return true;
    }
}

import java.util.*;

class WordDictionary {
    private final Set<String> patterns;

    public WordDictionary() {
        patterns = new HashSet<>();
    }

    public void addWord(String word) {
        patterns.add(word);
        char[] chars = word.toCharArray();
        for (int i = 0; i < chars.length; i++) {
            char originalI = chars[i];
            chars[i] = '.';
            patterns.add(new String(chars));
            for (int j = i + 1; j < chars.length; j++) {
                char originalJ = chars[j];
                chars[j] = '.';
                patterns.add(new String(chars));
                chars[j] = originalJ;
            }
            chars[i] = originalI;
        }
    }

    public boolean search(String word) {
        return patterns.contains(word);
    }
}
